import * as THREE from "three";
import build from "../../samples/barnstormerBiplane";

const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let meshes = 0;
let tris = 0;
const colors = new Set<string>();
const joints: string[] = [];
root.traverse((o) => {
  if ((o as THREE.Mesh).isMesh) {
    meshes++;
    const m = o as THREE.Mesh;
    const g = m.geometry;
    tris += (g.index ? g.index.count : g.attributes.position.count) / 3;
    const mat = m.material as THREE.MeshStandardMaterial;
    if (!mat.map) colors.add(mat.color.getHexString());
  } else if (o !== root) joints.push(o.name);
});
console.log("box", box.min.toArray().map((v) => v.toFixed(2)), box.max.toArray().map((v) => v.toFixed(2)));
console.log("size", box.getSize(new THREE.Vector3()).toArray().map((v) => v.toFixed(2)));
console.log("meshes", meshes, "tris", tris, "colors", colors.size, "joints", joints.length);
